import { readFile, readdir } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const defaultRoutesDirectory = fileURLToPath(
	new URL('../../src/routes/templates/', import.meta.url)
)
export const generatedFileHeader =
	'<!-- Generated by pnpm generate:template-routes; do not edit. -->\n'

/** @param {string | undefined} source */
export function isGeneratedTemplateRoute(source) {
	// Recognize adapters created before the scripts were moved into this folder.
	const previousHeader = '<!-- Generated by scripts/generate-template-routes.js; do not edit. -->\n'
	return (
		source !== undefined &&
		(source.startsWith(generatedFileHeader) || source.startsWith(previousHeader))
	)
}

/** @param {string} filePath */
export async function readFileIfPresent(filePath) {
	try {
		return await readFile(filePath, 'utf8')
	} catch (error) {
		if (error instanceof Error && 'code' in error && error.code === 'ENOENT') return undefined
		throw error
	}
}

/** @param {string} routesDirectory */
export async function findGeneratedTemplateRouteFiles(routesDirectory = defaultRoutesDirectory) {
	const generatedFiles = []
	for (const role of ['icon', 'page']) {
		let entries
		try {
			entries = await readdir(path.join(routesDirectory, role), {
				recursive: true,
				withFileTypes: true
			})
		} catch (error) {
			if (error instanceof Error && 'code' in error && error.code === 'ENOENT') continue
			throw error
		}
		for (const entry of entries) {
			if (!entry.isFile() || entry.name !== '+page.svelte') continue
			const filePath = path.join(entry.parentPath, entry.name)
			const source = await readFileIfPresent(filePath)
			if (isGeneratedTemplateRoute(source)) generatedFiles.push(filePath)
		}
	}
	return generatedFiles
}
